import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { ArrowLeft, Smartphone, CheckCircle, XCircle, Eye, Trash2, AlertTriangle } from 'lucide-react';
import Modal from '../../components/Modal';
import ConfirmationModal from '../../components/ConfirmationModal';

const initialReports = [
    { id: 'RG-0112', user: 'Amit S.', river: 'Ganga', location: 'Assi Ghat, Varanasi', status: 'Verified', date: '2024-07-20', image: 'data:image/jpeg;base64,', description: 'Large pile of plastic bottles and bags near the steps.' },
    { id: 'RG-0113', user: 'Priya M.', river: 'Yamuna', location: 'Okhla Bird Sanctuary', status: 'Pending', date: '2024-07-21', image: 'data:image/jpeg;base64,', description: 'White toxic foam covering a large area of the river surface.' },
    { id: 'RG-0114', user: 'Raj K.', river: 'Ganga', location: 'Bithoor, Kanpur', status: 'Rejected', date: '2024-07-19', image: 'data:image/jpeg;base64,', description: 'Duplicate report, area already scheduled for cleanup.' },
    { id: 'RG-0115', user: 'Sunita V.', river: 'Kaveri', location: 'Talakaveri', status: 'Verified', date: '2024-07-22', image: 'data:image/jpeg;base64,', description: 'Floating debris and offerings post-festival.' },
];

const statusStyles = {
    Verified: 'bg-green-100 text-green-800',
    Pending: 'bg-yellow-100 text-yellow-800',
    Rejected: 'bg-red-100 text-red-800',
};

const RiverGuardPage = () => {
    const [reports, setReports] = useState(initialReports);
    const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
    const [isConfirmModalOpen, setIsConfirmModalOpen] = useState(false);
    const [selectedReport, setSelectedReport] = useState(null);
    const [deletingReportId, setDeletingReportId] = useState(null);

    const handleViewDetails = (report) => {
        setSelectedReport(report);
        setIsDetailsModalOpen(true);
    };

    const handleCloseDetailsModal = () => {
        setIsDetailsModalOpen(false);
        setSelectedReport(null);
    };

    const handleOpenConfirmModal = (reportId) => {
        setDeletingReportId(reportId);
        setIsConfirmModalOpen(true);
    };

    const handleCloseConfirmModal = () => {
        setDeletingReportId(null);
        setIsConfirmModalOpen(false);
    };

    const handleUpdateStatus = (reportId, newStatus) => {
        setReports(reports.map(r => r.id === reportId ? { ...r, status: newStatus } : r));
        handleCloseDetailsModal();
    };

    const confirmDelete = () => {
        setReports(reports.filter(r => r.id !== deletingReportId));
        handleCloseConfirmModal();
        handleCloseDetailsModal();
    };

    return (
        <div className="py-12 bg-background-grey">
            <div className="container mx-auto px-4">
                <Link to="/" className="inline-flex items-center text-primary font-semibold mb-8 hover:underline">
                    <ArrowLeft size={20} className="mr-2" />
                    Back to Home
                </Link>
                <div className="flex justify-between items-center mb-8">
                    <h1 className="text-3xl font-bold text-text-dark flex items-center"><Smartphone className="mr-3"/>RiverGuard App Reports</h1>
                </div>
                
                <div className="mb-8 bg-blue-50 border-l-4 border-primary p-4 rounded-r-lg">
                    <div className="flex">
                        <div className="flex-shrink-0">
                            <AlertTriangle className="h-5 w-5 text-primary" />
                        </div>
                        <div className="ml-3">
                            <p className="text-sm text-blue-700">
                                Real-time hardware data is a future feature, currently in development.
                            </p>
                        </div>
                    </div>
                </div>

                <p className="mb-8 text-text-light max-w-3xl">Review and manage pollution reports submitted by citizens through the RiverGuard mobile app. Click on a report to view details and take action.</p>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {reports.map(report => (
                        <div key={report.id} className="bg-white rounded-xl shadow-md overflow-hidden transform hover:-translate-y-1 transition-transform">
                            <img src={report.image} alt={`Report from ${report.location}`} className="w-full h-48 object-cover" />
                            <div className="p-6">
                                <div className="flex justify-between items-start">
                                    <p className="font-mono text-sm text-primary">{report.id}</p>
                                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${statusStyles[report.status]}`}>{report.status}</span>
                                </div>
                                <h3 className="text-lg font-bold text-text-dark mt-2">{report.location}</h3>
                                <p className="text-sm text-secondary">{report.river} River</p>
                                <p className="text-sm text-secondary mt-1">Reported by: {report.user} on {report.date}</p>
                                <div className="mt-4 flex justify-end">
                                    <button onClick={() => handleViewDetails(report)} className="btn-primary flex items-center text-sm px-4 py-2">
                                        <Eye size={16} className="mr-2"/> View Details
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {selectedReport && (
                <Modal isOpen={isDetailsModalOpen} onClose={handleCloseDetailsModal} title={`Report Details: ${selectedReport.id}`}>
                    <div>
                        <img src={selectedReport.image} alt={`Full view of report from ${selectedReport.location}`} className="w-full h-64 object-cover rounded-lg mb-4" />
                        <h4 className="font-bold text-lg">{selectedReport.location}</h4>
                        <p className="text-secondary">{selectedReport.river} River</p>
                        <p className="mt-4 text-text-dark">{selectedReport.description}</p>
                        <div className="mt-6 pt-6 border-t border-border-color flex flex-wrap gap-4 justify-between">
                            <div>
                                {selectedReport.status === 'Pending' && (
                                    <div className="flex gap-4">
                                        <button onClick={() => handleUpdateStatus(selectedReport.id, 'Verified')} className="btn-success flex items-center"><CheckCircle size={18} className="mr-2"/>Verify</button>
                                        <button onClick={() => handleUpdateStatus(selectedReport.id, 'Rejected')} className="btn-warning flex items-center"><XCircle size={18} className="mr-2"/>Reject</button>
                                    </div>
                                )}
                            </div>
                             <button onClick={() => handleOpenConfirmModal(selectedReport.id)} className="btn-danger flex items-center"><Trash2 size={18} className="mr-2"/>Delete</button>
                        </div>
                    </div>
                </Modal>
            )}
            <ConfirmationModal 
                isOpen={isConfirmModalOpen}
                onClose={handleCloseConfirmModal}
                onConfirm={confirmDelete}
                title="Confirm Deletion"
                message={`Are you sure you want to delete report ${deletingReportId}? This action cannot be undone.`}
            />
        </div>
    );
};

// Add some base styles in a utility file or here for simplicity
const styles = `
.btn-success {
    @apply inline-block bg-success text-white font-semibold px-6 py-2.5 rounded-lg hover:bg-green-600 transition-colors;
}
.btn-warning {
    @apply inline-block bg-warning text-white font-semibold px-6 py-2.5 rounded-lg hover:bg-amber-500 transition-colors;
}
.btn-danger {
    @apply inline-block bg-danger text-white font-semibold px-6 py-2.5 rounded-lg hover:bg-red-600 transition-colors;
}
`;

const styleSheet = document.createElement("style");
styleSheet.innerText = styles;
document.head.appendChild(styleSheet);

export default RiverGuardPage;
